"""Build a fully executable notebook; run execute_notebook.py afterwards."""
from pathlib import Path
import nbformat as nbf
ROOT=Path(__file__).resolve().parent
CELLS=[('markdown', '# DL091 预测世界模型与模型式决策\n\n本Notebook在新Python进程的真实IPython内核内顺序执行，完整运行实验和测试。先读 lecture.md 与 lab.md。只验证离线合成教学任务，不代表自然数据性能或部署保证。'), ('code', 'from pathlib import Path\nimport sys,json\nimport numpy as np\nimport experiment as exp\nprint("Python",sys.version.split()[0],"NumPy",np.__version__)'), ('markdown', '## 完整重训与数据保存\n运行覆盖本目录 outputs 和 figures 中的同名文件；无下载、无GPU、无付费API。'), ('code', 'result=exp.main("outputs")'), ('markdown', '## 手算对应的真实一步与隐藏速度'), ('code', 'print(exp.true_step(np.array([1.,0.]),0.))\nprint(exp.true_step(np.array([[1.,.5],[1.,-.5]]),np.zeros(2)))\ns,a=exp.generate(9101)\ns0,aa,target=exp.windows(s,a,5)\nprint("trajectory",s.shape,"windows",s0.shape,aa.shape,target.shape)'), ('markdown', '## 训练目标与控制结果'), ('code', 'for row in result["runs"]:\n    print(row["method"],row["seed"],"training five-step MSE",row["training_five_step_mse"])\nprint(json.dumps(result["control_summary"],indent=2))\nprint(result["partial_observation"])'), ('markdown', '## 单元测试\n检查计算与边界，不只观察训练损失。'), ('code', 'import unittest\nsuite=unittest.defaultTestLoader.discover(str(Path.cwd()),pattern="test_experiment.py")\ncheck=unittest.TextTestRunner(verbosity=2).run(suite)\nif not check.wasSuccessful(): raise RuntimeError("tests failed")'), ('markdown', '## 保存文件的独立推理重放'), ('code', 'import verify_replay\nreplay=verify_replay.main("outputs")\nprint(replay)'), ('markdown', '## 原创图的真实结果\n图为本次实验直接重建。'), ('code', 'from IPython.display import display,Image\nfor path in sorted(Path("figures").glob("*.png")):\n    print(path.name)\n    display(Image(filename=str(path)))'), ('markdown', '## 研究记录\n请写下一个受证据支持的主张、一个负结果或限制、一个明确的新检验。不要用参考答案替代自己的数据检查。'), ('code', 'print("Saved outputs:",sorted(p.name for p in Path("outputs").iterdir() if p.is_file()))')]
def main():
    cells=[nbf.v4.new_code_cell(text) if kind=="code" else nbf.v4.new_markdown_cell(text) for kind,text in CELLS]
    nb=nbf.v4.new_notebook(cells=cells,metadata={"kernelspec":{"display_name":"Python 3","language":"python","name":"python3"},"language_info":{"name":"python","version":"3.12"}})
    nbf.write(nb,ROOT/"experiment.ipynb")
if __name__=="__main__":main()
